<script setup>import { computed } from "vue"; const props = defineProps({ status: { type: String, required: true } }); const labels = { disponible: "Disponible", en_attente: "En attente", approuve: "Approuvée", refuse: "Refusée", restitue: "Restituée", maintenance: "Maintenance", retire: "Retiré" }; const styles = { disponible: "badge-success", approuve: "badge-success", en_attente: "badge-warning", refuse: "badge-error", restitue: "badge-info", maintenance: "badge-warning", retire: "badge-neutral" }; const label = computed(() => labels[props.status] || props.status); const style = computed(() => styles[props.status] || "badge-ghost");</script><template><span class="badge whitespace-nowrap" :class="style">{{ label }}</span></template>
